function solve(a,b){if(b.length===0||a.length<b.length){return'';}const m=h(b.split(''));let c=b.length;let r=0;let n=0;let d=Infinity;for(let i=0;i<a.length;i+=1){const x=a[i];if(m[x]!==undefined){if(m[x]>0){c-=1;}m[x]-=1;}while(c===0){const b=i-r+1;if(b<d){n=r;d=b;}const x=a[r];r+=1;if(m[x]!==undefined){m[x]+=1;if(m[x]>0){c+=1;}}}}return d===Infinity?'':a.slice(n,n+d);}function h(a){const m={};for(const x of a){m[x]=(m[x]||0)+1;}return m;}